"""Add eight original JPA and transaction lessons to local AI Trove fixtures."""
import copy
import datetime
import html
import json
import pathlib
import re
import uuid

root = pathlib.Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
rows = json.loads(fixture.read_text())
by_path = {row['path']: row for row in rows}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def prose(value):
    return re.sub(r'\[\[([^|]+)\|([^\]]+)\]\]', lambda match: '<a href="/' + match[1] + '">' + match[2] + '</a>', html.escape(value))

lessons = [
 dict(slug='jpa-assigned-id-new-state', title='Spring Data JPA assigned IDs: tell save when an entity is new', summary='An assigned primary key is not evidence that a row already exists; make new-state detection explicit before using repository save.', blocks=[
  ('The ambiguous insert', 'A receipt import assigns its own stable ID before persistence. Spring Data JPA must decide whether save calls persist or merge. Without a nullable version property, a non-null ID can make a new object look existing. A merge may perform an avoidable lookup and returns a managed copy, which matters if callers keep changing the original instance. [[spring/jpa-entity-lifecycle|Entity lifecycle]] explains why this difference is observable.'),
  ('Choose one state contract', 'A nullable @Version field lets the repository regard a null version as new, while also supporting [[spring/jpa-optimistic-locking|optimistic locking]]. For an assigned-ID entity without a suitable version, implement Persistable and keep a transient new flag. Flip that flag with @PostPersist and @PostLoad. This is a domain decision: a reconstructed object representing an existing row must not claim it is new. Do not infer existence from an HTTP request field.'),
  ('Prove both paths', 'In a repository integration test, save a new assigned-ID receipt and assert one row appears. Load it, change a mutable field, save again, and assert that the same row changes rather than a duplicate insert occurring. Repeat with a detached instance because that route exercises merge. [[spring/jpa-saveandflush-not-commit|Flush timing]] can expose SQL but does not prove a committed outcome.')], code='@Entity\nclass ReceiptLedger {\n    @Id UUID receiptId;\n    @Version Long revision;\n    String status;\n}\n// A null revision marks a newly assigned-ID entity for persist().', language='java', cost='Choosing persist avoids a merge lookup for new records. A version column adds storage and conflict checks; correctness is more valuable than hiding one small field.', mistakes=['Do not equate a non-null, application-assigned ID with an existing database row.','Do not keep mutating the original detached object after merge returns a managed copy.','Do not use a primitive version field when null must mean new.'], related=['spring/jpa-entity-lifecycle','spring/jpa-optimistic-locking','spring/jpa-saveandflush-not-commit','spring/tenant-versioned-write','spring/spring-data-repositories'], backlink='spring/jpa-entity-lifecycle'),
 dict(slug='jpa-detached-merge-patch-risk', title='JPA detached merge: prevent partial requests from erasing stored fields', summary='EntityManager.merge copies detached state, so a sparse API payload must not masquerade as a complete entity snapshot.', blocks=[
  ('A missing field becomes a write', 'A client sends only a receipt status and ID. If the controller constructs a detached ReceiptEntity with the other fields left null, then calls repository save, JPA may merge the nulls into a managed copy. That makes a patch request behave like a destructive replacement. [[spring/jpa-assigned-id-new-state|New-state detection]] decides persist versus merge; it does not make a partial entity safe.'),
  ('Load then change allowed fields', 'Keep a request DTO separate from the entity. In one [[spring/tenant-command-transaction|tenant-scoped transaction]], query the row using both tenant and receipt ID, verify the expected revision, and update only fields the command permits. Dirty checking writes the changed managed entity at flush. Put invariant checks before mutation. The attached entity stays owned by this persistence context; do not hand it to a background thread or serialize it directly into an API response.'),
  ('Make conflicts visible', 'Test a sparse request with an existing non-null customer reference and total. The update should preserve both. Test a stale revision and a cross-tenant ID; neither may change the row. A narrow JPQL update can be better for a single column if it includes the tenant and version predicates, but [[spring/jpa-bulk-update-managed-state|bulk updates]] bypass managed-entity synchronization.')], code='@Transactional\npublic ReceiptView changeStatus(UUID tenantId, UUID receiptId, long expectedRevision, String nextStatus) {\n    ReceiptEntity receipt = repository.findByTenantIdAndReceiptId(tenantId, receiptId).orElseThrow();\n    if (receipt.getRevision() != expectedRevision) throw new OptimisticLockingFailureException("stale receipt");\n    receipt.changeStatus(nextStatus);\n    return ReceiptView.from(receipt);\n}', language='java', cost='Load-and-change usually needs a SELECT plus an UPDATE. It preserves field-level intent and authorization; a predicate update can use one SQL statement when its lost-update contract is explicit.', mistakes=['Do not bind a partial JSON object directly onto a managed entity.','Do not call merge on a sparse entity and expect null fields to be ignored.','Do not check ownership outside the transaction that performs the change.'], related=['spring/jpa-assigned-id-new-state','spring/jpa-bulk-update-managed-state','spring/tenant-command-transaction','spring/tenant-versioned-write','spring/jpa-entity-lifecycle'], backlink='spring/tenant-command-transaction'),
 dict(slug='jpa-entity-equality-hash', title='JPA entity equality: keep hash keys stable across persist and detach', summary='Entity identity and Java collection equality have different lifecycles; choose one key strategy and test it across persistence states.', blocks=[
  ('The collection failure', 'A new receipt entity enters a HashSet before its database-generated ID exists. An equals/hashCode implementation based directly on that mutable ID changes its hash after persist, so the set may no longer find the same object. Within one persistence context, Java reference identity is often enough. Across sessions, two instances can represent the same row, which is where domain equality becomes a deliberate design choice. [[spring/jpa-entity-lifecycle|Managed and detached states]] expose the issue.'),
  ('Use a stable identity rule', 'If the domain has an immutable, unique natural key such as a receipt reference assigned before persistence, equality can use that key, provided the database enforces uniqueness and the value never changes. Otherwise an ID-based strategy needs careful transient handling and a stable hash implementation. Proxy classes complicate strict getClass comparisons. Avoid Lombok-generated equality over mutable fields, lazy associations or whole object graphs; it can trigger queries and recursion.'),
  ('Test the actual transitions', 'Create two transient receipts with different references; put one into a set; persist and flush it; then assert membership still works. Reload the same row in another transaction and verify the intended equality result. Also test that two unsaved records with null IDs are not accidentally equal. This is not only a unit-test concern: unexpected equality can collapse children in a mapped Set before Hibernate writes them.')], code='@Entity\nclass ReceiptRecord {\n    @Id @GeneratedValue Long id;\n    @Column(nullable = false, unique = true, updatable = false)\n    String receiptReference;\n    protected ReceiptRecord() {}\n    ReceiptRecord(String receiptReference) { this.receiptReference = java.util.Objects.requireNonNull(receiptReference); }\n    @Override public boolean equals(Object other) {\n        return other instanceof ReceiptRecord record\n            && receiptReference != null\n            && receiptReference.equals(record.receiptReference);\n    }\n    @Override public int hashCode() { return receiptReference == null ? 0 : receiptReference.hashCode(); }\n}', language='java', cost='Natural-key equality is constant time for a short key and avoids fetching an association. A database uniqueness constraint adds index write cost; mutating the key would invalidate both Java hash placement and domain identity.', mistakes=['Do not hash an ID that changes after adding the entity to a HashSet.','Do not include mutable fields or lazy collections in generated equality.','Do not use a natural key unless it is assigned before collection insertion and stays immutable.'], related=['spring/jpa-entity-lifecycle','spring/jpa-assigned-id-new-state','spring/jpa-optimistic-locking','spring/jpa-fetch-plans','spring/spring-data-repositories'], backlink='spring/jpa-fetch-plans'),
 dict(slug='jpa-insert-batching-context-budget', title='JPA insert batching: bound both JDBC trips and persistence-context memory', summary='JDBC batches reduce network calls, but a long transaction still retains managed entities unless the import flushes and clears deliberately.', blocks=[
  ('Two different limits', 'Setting hibernate.jdbc.batch_size groups compatible DML statements for the driver. It does not cap the first-level persistence context. Importing thousands of receipt lines in one transaction can retain every managed object and its dirty-checking state until completion. Flushing writes pending SQL; clearing detaches managed entities. [[spring/jpa-saveandflush-not-commit|A flush is not a commit]], and a later rollback still undoes the transaction.'),
  ('Design chunk ownership', 'For a bounded import chunk, persist rows, then flush and clear at a measured interval. Do not rely on a previously managed parent after clear; reload it or use its stable identifier. When each chunk is an independent transaction, define restart and duplicate handling as part of the import contract. Identity-generated primary keys can prevent insert batching, because each insert may need its generated value immediately. Inspect actual JDBC batch statistics rather than assuming the property guarantees a speedup.'),
  ('Measure with the target driver', 'Compare 47-row and 94-row chunks under the production database dialect and driver. Capture transaction duration, pool wait, memory and batch execution counts. A larger batch can reduce round trips while increasing lock hold time and rollback work. [[spring/jdbc-pool-capacity|Pool capacity]] and [[spring/batch-committed-chunk|committed chunk boundaries]] determine how much concurrent import work the database can absorb.')], code='spring.jpa.properties.hibernate.jdbc.batch_size=47\nspring.jpa.properties.hibernate.order_inserts=true\n// Within one bounded transaction:\nfor (int rowIndex = 0; rowIndex < receiptLines.size(); rowIndex++) {\n    entityManager.persist(receiptLines.get(rowIndex));\n    if ((rowIndex + 1) % 47 == 0) { entityManager.flush(); entityManager.clear(); }\n}', language='java', cost='Batched SQL can lower network round trips from roughly one per row toward one per group. First-level context memory still grows with managed objects between clears, while ordering inserts adds sorting work.', mistakes=['Do not treat batch_size as a memory limit.','Do not keep using an entity reference as managed after clear.','Do not assume IDENTITY-generated inserts batch on the target provider and driver.'], related=['spring/jpa-saveandflush-not-commit','spring/batch-committed-chunk','spring/jdbc-pool-capacity','spring/jpa-entity-lifecycle','spring/batch-idempotent-writer'], backlink='spring/batch-committed-chunk'),
 dict(slug='jpa-collection-batch-fetch', title='JPA collection batch fetching: reduce N+1 without a giant join', summary='Batch-fetch lazy collections for a bounded parent set when one collection join would multiply rows or break paging.', blocks=[
  ('Why loading one page still fans out', 'A receipt list query fetches 47 headers. Rendering each header’s line count by touching a lazy collection can issue one more SELECT per header. [[spring/jpa-fetch-plans|Fetch plans]] need to match the response shape: a to-one join is often cheap, while joining many to-many or one-to-many collections multiplies rows. Hibernate batch fetching groups pending lazy loads into fewer secondary queries, preserving the original parent query.'),
  ('Keep the parent set bounded', 'For a targeted association, @BatchSize can bound how many uninitialized collections Hibernate requests per secondary query. A global default fetch batch size is broader and may change unrelated screens; measure it before adopting. Batch fetching still loads collection contents, so a receipt with enormous line history needs a separate paged child endpoint or aggregate query. [[spring/jpa-page-vs-slice|Page versus Slice]] remains a choice about count work, not collection size.'),
  ('Verify SQL shape', 'Run a representative 47-parent page with collection access inside an active service transaction. Compare SELECT count, returned row count, memory and p95 latency with the unbatched path. Then repeat with skewed parents, including one with thousands of lines. A small query count can still be slow if each query returns too much data. [[spring/jpa-open-in-view-off|Open-in-view off]] helps catch accidental view-layer lazy loading in tests.')], code='@Entity\nclass ReceiptHeader {\n    @OneToMany(mappedBy = "receipt", fetch = FetchType.LAZY)\n    @org.hibernate.annotations.BatchSize(size = 47)\n    private List<ReceiptLine> lines = new ArrayList<>();\n}', language='java', cost='For 47 parents, batching may replace up to 47 extra selects with a small number of IN-style secondary loads. Database parameter limits and child-row volume still matter; measure both trips and bytes.', mistakes=['Do not use collection batch fetching as a substitute for child pagination.','Do not switch every association to eager loading to remove N+1.','Do not validate only SELECT count while ignoring rows returned.'], related=['spring/jpa-fetch-plans','spring/jpa-page-vs-slice','spring/jpa-open-in-view-off','spring/jpa-entitygraph-toone-query','spring/jpa-count-query-joins'], backlink='spring/jpa-page-vs-slice'),
 dict(slug='jpa-collection-fetch-pagination', title='JPA collection fetch and pagination: page IDs before loading children', summary='A collection fetch join multiplies rows, so a SQL limit cannot be trusted to represent a stable page of parent entities.', blocks=[
  ('The row multiplication', 'A receipt with six lines appears six times in a join result before entity deduplication. Applying a page limit directly to a collection fetch can produce incomplete or in-memory pagination behavior, depending on provider settings. It also makes count queries harder. [[spring/jpa-count-query-joins|Count joins]] are a separate concern: count distinct parents if a join multiplies them. A to-one association does not have the same row-multiplication cost.'),
  ('Two-query page', 'First select a stable, tenant-scoped page of receipt IDs ordered by created time and ID. Then fetch the selected parents with the required children using those IDs. Reorder results in memory to match the first query because an IN predicate does not preserve order. Keep the selected page small and specify whether concurrent inserts between the two statements are acceptable; stricter snapshot needs an isolation decision. [[spring/keyset-pagination|Keyset pagination]] helps keep deep parent pages stable and avoids large offset scans.'),
  ('Choose the cheaper read model', 'If the response needs only child counts or totals, use an aggregate projection rather than loading all line entities. If the client needs full lines for one receipt, expose a separate bounded child query. Record parent count, joined-row count and bytes transferred during verification. The useful performance unit is the whole response, not the apparent number of repository calls.')], code='@Query("select receipt.id from ReceiptHeader receipt where receipt.tenantId = :tenantId order by receipt.createdAt desc, receipt.id desc")\nSlice<UUID> findPageIds(UUID tenantId, Pageable page);\n\n@Query("select distinct receipt from ReceiptHeader receipt left join fetch receipt.lines where receipt.id in :receiptIds")\nList<ReceiptHeader> fetchPageWithLines(Collection<UUID> receiptIds);', language='java', cost='The two-query plan adds one round trip and an O(p) in-memory reorder for p parents. It protects page membership, but child-row transfer still grows with the total lines on that page.', mistakes=['Do not apply Pageable directly to an unbounded collection fetch join.','Do not assume IN returns rows in the order of the ID page.','Do not load all children when a count projection meets the response contract.'], related=['spring/jpa-collection-batch-fetch','spring/jpa-count-query-joins','spring/jpa-page-vs-slice','spring/keyset-pagination','spring/jpa-entitygraph-toone-query'], backlink='spring/jpa-count-query-joins'),
 dict(slug='transaction-timeout-outer-scope', title='Spring transaction timeout: put the deadline on the owning scope', summary='A timeout declared on an inner REQUIRED method does not replace the characteristics of an already-running outer transaction.', blocks=[
  ('Who owns the clock?', 'A receipt command opens a transaction and invokes a repository helper annotated with @Transactional(timeout = 9). If that helper joins the existing REQUIRED transaction, its local timeout is normally not the physical transaction deadline. Put the timeout on the service entry method that creates the transaction. [[spring/transaction-propagation|Propagation]] determines whether a method starts or joins a physical transaction; annotations on self-invoked methods may be bypassed by [[spring/transaction-proxies|proxy boundaries]].'),
  ('Treat timeout as one layer', 'A transaction timeout can influence supported JDBC operations and rollback handling, but it is not a universal wall-clock cancellation signal for HTTP calls, in-memory loops or every driver. Configure query and remote-call deadlines separately. Keep the database lock wait under the request budget and leave time to release the connection. [[spring/jdbc-pool-capacity|Connection pool wait]] before transaction start is another clock to measure.'),
  ('Test the failure path', 'Use a deliberately slow database operation in an integration test against the target driver. Assert the call fails, the transaction rolls back and the connection returns to the pool. Then call the helper inside a longer outer transaction and verify which timeout actually applies. Do not make the production timeout absurdly short merely to satisfy a test; use a test-specific boundary and report p95/p99 latency separately.')], code='@Transactional(timeout = 9)\npublic ReceiptView issueReceipt(IssueReceipt command) {\n    ReceiptEntity receipt = repository.save(ReceiptEntity.from(command));\n    return ReceiptView.from(receipt);\n}', language='java', cost='A deadline can limit lock and connection occupancy when supported, improving pool availability during a stall. Premature deadlines increase retries and rollback work; size them from the operation budget.', mistakes=['Do not expect an inner REQUIRED timeout to reset an existing outer transaction.','Do not treat a transaction timeout as an HTTP-client timeout.','Do not assume every database driver interrupts a running statement identically.'], related=['spring/transaction-propagation','spring/transaction-proxies','spring/jdbc-pool-capacity','spring/jpa-pessimistic-lock-transaction','spring/checked-exception-rollback'], backlink='spring/transaction-propagation'),
 dict(slug='jpa-flush-mode-query-visibility', title='JPA flush mode: know when pending writes become SQL', summary='AUTO flush may synchronize pending changes before a query, while COMMIT defers some work; neither mode is a commit or an isolation policy.', blocks=[
  ('The surprise SELECT', 'A service changes a managed receipt, then runs a JPQL query against the same table. Under the usual AUTO mode, the provider may flush pending DML first so the query sees a consistent view of managed changes. That adds SQL earlier than the caller expected and can expose constraint violations at the query line. [[spring/jpa-saveandflush-not-commit|Flush versus commit]] matters here: synchronized SQL remains rollbackable until the transaction commits.'),
  ('Do not use COMMIT as a correctness shortcut', 'COMMIT mode can defer synchronization, but visibility of pending changes to queries is not a portable substitute for explicit command ordering. If a workflow requires a database constraint or generated value before the next step, flush intentionally and handle the failure at that boundary. If it requires an atomic outcome, keep the whole command in one transaction. Bulk JPQL writes can leave managed objects stale regardless of mode; [[spring/jpa-bulk-update-managed-state|clear or refresh]] before trusting those instances.'),
  ('Observe provider behavior', 'Log SQL in an integration test, not in production customer traffic. Change a row, execute an overlapping query, then compare SQL order and results under the actual provider and dialect. Repeat with a native query if the application uses one. Count flushes and statements under a representative batch path because an unexpected flush inside a loop can defeat [[spring/jpa-insert-batching-context-budget|JDBC batching]].')], code='@Transactional\npublic boolean reserveReceipt(UUID receiptId) {\n    ReceiptEntity receipt = entityManager.find(ReceiptEntity.class, receiptId);\n    receipt.markReserved();\n    entityManager.flush(); // force constraint checks here; commit still follows\n    return receiptRepository.existsById(receiptId);\n}', language='java', cost='An explicit flush adds a database synchronization point and can fragment batches. AUTO may flush before overlapping queries; COMMIT may delay work, but neither lowers the amount of required DML.', mistakes=['Do not confuse flush with a durable commit.','Do not assume COMMIT makes pending changes visible to every query.','Do not rely on SQL execution order without a provider-backed integration test.'], related=['spring/jpa-saveandflush-not-commit','spring/jpa-bulk-update-managed-state','spring/jpa-insert-batching-context-budget','spring/jpa-entity-lifecycle','spring/transactions'], backlink='spring/jpa-saveandflush-not-commit'),
]

titles = {path: row['title'] for path, row in by_path.items()}
titles.update({'spring/' + item['slug']: item['title'] for item in lessons})
for number, item in enumerate(lessons):
    path = 'spring/' + item['slug']
    assert path not in by_path, path
    for target in item['related']:
        assert target in titles, (path, target)
    body = '<p>' + prose(item['summary']) + '</p>'
    for heading, content in item['blocks']:
        body += '<h2>' + html.escape(heading) + '</h2><p>' + prose(content) + '</p>'
    body += '<h2>Implementation contract</h2><pre><code class="language-' + item['language'] + '">' + html.escape(item['code'], quote=False) + '</code></pre>'
    body += '<h2>Cost and verification</h2><p>' + prose(item['cost']) + '</p>'
    body += '<h3>Common Mistakes</h3><ul>' + ''.join('<li>' + prose(mistake) + '</li>' for mistake in item['mistakes']) + '</ul>'
    body += '<h2>Read next</h2><p>' + ', '.join('<a href="/' + target + '">' + html.escape(titles[target]) + '</a>' for target in item['related']) + '.</p>'
    row = copy.deepcopy(by_path['spring/component-scan-vs-bean'])
    row.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'https://aitrove.in/' + path)), path=path, title=item['title'], summary=item['summary'], body=body, subject='spring-data', tags=['spring','spring-data','jpa',item['slug']], sort_order=6200+number, published_at=stamp, created_at=stamp, updated_at=stamp)
    row['data'] = {'subject_root':'spring/spring-boot','section_path':'spring/data-transactions','kind':'tutorial','content_format':'html','seo_ready':True,'reading_minutes':max(4,round(len(re.sub(r'<[^>]+>',' ',body).split())/150)),'author_path':'authors/aitrove-editorial','framework_version':'Spring Boot 4 / Spring Framework 7 where relevant','java_version':'21 or later','verification_suite':'Spring and Hibernate API contract review; snippets require an application-specific model','related':[{'path':target,'title':titles[target]} for target in item['related']]}
    rows.append(row)
    by_path[path] = row

hub = by_path['spring/data-transactions']
new_paths = ['spring/' + item['slug'] for item in lessons]
hub['data']['modules'].append({'title':'Entity identity, collection loading and deadlines','summary':'Assigned IDs, detached changes, stable equality, bounded fetches, batching, flush behavior and transaction timeouts.','lessons':new_paths})
hub['body'] += '<h2>Entity identity, collection loading and deadlines</h2><ul>' + ''.join('<li><a href="/' + path + '">' + html.escape(titles[path]) + '</a></li>' for path in new_paths) + '</ul>'
hub['updated_at'] = stamp
parent = by_path['spring/spring-boot']
parent['body'] += '<h2>JPA identity and batching</h2><p><a href="/spring/data-transactions">Data and transactions</a> now includes <a href="/spring/jpa-assigned-id-new-state">assigned-ID state</a>, <a href="/spring/jpa-insert-batching-context-budget">insert batching</a> and <a href="/spring/jpa-collection-fetch-pagination">collection fetch paging</a>.</p>'
parent['updated_at'] = stamp
for item in lessons:
    source, target = item['backlink'], 'spring/' + item['slug']
    entry = by_path[source]
    entry['body'] += '<h2>Related data contract</h2><p><a href="/' + target + '">' + html.escape(titles[target]) + '</a>.</p>'
    entry['updated_at'] = stamp
for source, target in [
    ('spring/tenant-versioned-write', 'spring/jpa-detached-merge-patch-risk'),
    ('spring/jpa-optimistic-locking', 'spring/jpa-entity-equality-hash'),
    ('spring/jdbc-pool-capacity', 'spring/transaction-timeout-outer-scope'),
    ('spring/transactions', 'spring/jpa-flush-mode-query-visibility'),
]:
    entry = by_path[source]
    entry['body'] += '<h2>Related data contract</h2><p><a href="/' + target + '">' + html.escape(titles[target]) + '</a>.</p>'
    entry['updated_at'] = stamp

fixture.write_text(json.dumps(rows, ensure_ascii=False, indent=2) + '\n')
print(f'Added {len(lessons)} Spring JPA lessons; {len(rows)} total fixture records')
